export function rotationYQuaternion(value: number): [number, number, number, number] { return [0, Math.sin(value / 2), 0, Math.cos(value / 2)]; }

export function eulerQuaternion([x, y, z]: Hyperfocus3DVec3): [number, number, number, number] { const cx = Math.cos(x / 2), sx = Math.sin(x / 2), cy = Math.cos(y / 2), sy = Math.sin(y / 2), cz = Math.cos(z / 2), sz = Math.sin(z / 2); return [sx * cy * cz + cx * sy * sz, cx * sy * cz - sx * cy * sz, cx * cy * sz + sx * sy * cz, cx * cy * cz - sx * sy * sz]; }

export function interpolate3(from: Hyperfocus3DVec3, to: Hyperfocus3DVec3, amount: number): Hyperfocus3DVec3 { return [mix(from[0], to[0], amount), mix(from[1], to[1], amount), mix(from[2], to[2], amount)]; }

export function interpolateAngles(from: Hyperfocus3DVec3, to: Hyperfocus3DVec3, amount: number): Hyperfocus3DVec3 { return tuple3(from[(0)]! + shortestAngle(to[(0)]! - from[(0)]!) * amount, from[(1)]! + shortestAngle(to[(1)]! - from[(1)]!) * amount, from[(2)]! + shortestAngle(to[(2)]! - from[(2)]!) * amount); }

export function shortestAngle(value: number) { return Math.atan2(Math.sin(value), Math.cos(value)); }

export function copy3(value: readonly number[]): Hyperfocus3DVec3 { return [value[0]!, value[1]!, value[2]!]; }

export function add3(left: Hyperfocus3DVec3, right: Hyperfocus3DVec3): Hyperfocus3DVec3 { return [left[0] + right[0], left[1] + right[1], left[2] + right[2]]; }

export function declaredBoneAncestor(bones: readonly { id: string; parentId?: string }[], ancestorId: string, childId: string) { const parentById = new Map(bones.map((bone) => [bone.id, bone.parentId] as const)), visited = new Set<string>(); for (let current: string | undefined = childId; current && !visited.has(current); current = parentById.get(current)) { if (current === ancestorId) return true; visited.add(current); } return false; }

export function mix(from: number, to: number, amount: number) { return from + (to - from) * amount; }

export function smootherstep(value: number) { const t = Math.max(0, Math.min(1, value)); return t * t * t * (t * (t * 6 - 15) + 10); }

export function diagnostic(code: string, pointer: string, feature: string, boundary: Hyperfocus3DFrameDiagnostic["boundary"], message: string, alternative?: string): Hyperfocus3DFrameDiagnostic { return { severity: "error", code, pointer, feature, boundary, message, ...(alternative ? { alternative } : {}) }; }
